# Geometry constraints
core_ids=[3,16,ra,clidx,rb,1]
core=np.load('core.npy')
def setdist(i,j,d,w=.06):
    b[min(i,j),max(i,j)]=d+w
    b[max(i,j),min(i,j)]=max(.1,d-w)
# Loosen default bounds involving rhodium and the bridging chloride,
# since ordinary valence templates do not describe pi coordination.
for i in [ra,rb,clidx]:
 for j in range(m.GetNumAtoms()):
  if i!=j:
   b[min(i,j),max(i,j)]=100.0
   b[max(i,j),min(i,j)]=1.3
for k,i in enumerate(core_ids):
 for l,j in enumerate(core_ids[:k]):setdist(i,j,np.linalg.norm(core[k]-core[l]),.06)
for rh,donor,ids in zip([ra,rb],[16,1],cods):
    for i in [ids[0],ids[1],ids[4],ids[5]]:setdist(i,rh,2.18,.06)
    # donors are trans to alkene centroids
    dr=np.linalg.norm(core[core_ids.index(rh)]-core[core_ids.index(donor)])
    cr=2.4
    for i in [ids[0],ids[1]]:
      setdist(i,donor,np.sqrt((dr+2.075)**2+.69**2),.12)
      setdist(i,clidx,np.sqrt(cr**2+2.18**2),.23)
    for i in [ids[4],ids[5]]:
      setdist(i,clidx,np.sqrt((cr+2.075)**2+.69**2),.12)
      setdist(i,donor,np.sqrt(dr**2+2.18**2),.23)
params=AllChem.ETKDGv3();params.randomSeed=41;params.numThreads=4
params.SetBoundsMat(b);params.useRandomCoords=True;params.maxIterations=3000
params.ignoreSmoothingFailures=True
cids=AllChem.EmbedMultipleConfs(m, numConfs=8, params=params)
print('Embedded:',list(cids))
for idx in cids:
 xyz=np.array(m.GetConformer(idx).GetPositions())
 with open('initial_%d.xyz'%idx,'w') as f:
  f.write(f'{len(xyz)}\nRh2 Ge aminophosphine complex with two 1,5-cyclooctadiene ligands\n')
  for atom,pos in zip(m.GetAtoms(),xyz):f.write(f'{atom.GetSymbol():2s} {pos[0]: .8f} {pos[1]: .8f} {pos[2]: .8f}\n')
np.save('bounds.npy',b)
